onClick:
{{
  Update_Acompte_Commande.run()
    .then(() => {
      // 1. Fermer la modale et prévenir l'utilisateur
      closeModal('modal_generer_acompte');
      showAlert('Génération de la facture en cours... Le PDF apparaîtra d\'ici quelques secondes.', 'info');

      // 2. Initialiser le compteur de Polling
      let pollCount = 0;
      const maxPolls = 45; // 45 secondes max (15 essais * 3s)

      // 3. Lancer la boucle
      const pollInterval = setInterval(() => {
        pollCount++;

        // Rafraîchir les données de la commande
        Get_Commande_ById.run().then(() => {
          const commande = Get_Commande_ById.data[0];

          // Vérifier si le lien de la facture est enfin arrivé
          if (commande.Lien_Facture_Acompte && commande.Statut_Acompte === 'Facturé') {
            clearInterval(pollInterval); // Arrêter la boucle
            showAlert('Facture générée !', 'success');
            // L'Iframe apparaîtra toute seule grâce à sa propriété Visible
          } 
          // Si le temps est écoulé (timeout de sécurité)
          else if (pollCount >= maxPolls) {
            clearInterval(pollInterval);
            showAlert('Le traitement est anormalement long. Veuillez rafraîchir manuellement dans 1 minute.', 'warning');
          }
        });
      }, 1000); // Exécuter toutes les 3 secondes
    })
    .catch((err) => {
      showAlert('Erreur d\'envoi : ' + err.message, 'error');
    });
}}
